const now = new Date();
const dow = now.getDay(); // Friday = 5
const diffToMonday = dow === 0 ? -6 : 1 - dow;
const monday = new Date(now);
monday.setDate(now.getDate() + diffToMonday);

const thisWeekStart = monday.toISOString().slice(0, 10);
const lastMonday = new Date(monday);
lastMonday.setDate(monday.getDate() - 7);
const lastWeekStart = lastMonday.toISOString().slice(0, 10);

const dateLabel = monday.toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' });

return [{ json: { thisWeekStart, lastWeekStart, dateLabel } }];

function asRows(x) {
  if (Array.isArray(x)) return x;
  if (x && Array.isArray(x.data)) return x.data;
  return x ? [x] : [];
}

const ranges = $('Compute Week Ranges').first().json;
const thisWeek = asRows($('Get This Week Score').first().json);
const lastWeek = asRows($input.first().json);

const MAX_POINTS = {
  'S - Social Media': 10,
  'C - Classes': 5,
  'C - Signed Agreements': null,
  'O - Open Houses': null,
  'R - 5x5 Conversations': 25,
  'R - Command Opportunities': null,
  'E - CMA': 20,
};

const thisTotal = thisWeek.reduce((sum, c) => sum + (c.points || 0), 0);
const lastTotal = lastWeek.reduce((sum, c) => sum + (c.points || 0), 0);

const thisWeekWithMax = thisWeek.map(c => ({ ...c, max_points: MAX_POINTS[c.category] }));

return [{
  json: {
    thisWeekStart: ranges.thisWeekStart,
    dateLabel: ranges.dateLabel,
    thisTotal,
    lastTotal,
    thisWeek: thisWeekWithMax,
    lastWeek,
  }
}];

const merged = $('Merge & Compute Totals').first().json;
const response = $input.first().json;

function stripFences(text) {
  return text.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
}

let reportCard = '';
let headline = '';

try {
  const rawText = response.content?.[0]?.text || '';
  const parsed = JSON.parse(stripFences(rawText));
  reportCard = parsed.report_card || '';
  headline = parsed.headline || '';
} catch (err) {
  reportCard = (response.content?.[0]?.text || 'Report card generation failed — check n8n execution log.').trim();
  headline = `Week wrapped \u2014 ${merged.thisTotal} pts!`;
}

return [{
  json: {
    reportCard,
    headline,
    thisTotal: merged.thisTotal,
    dateLabel: merged.dateLabel,
  }
}];
